func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) error {
	_, err := q.db.ExecContext(ctx, updateProduct,
		arg.Code,
		arg.Name,
		arg.CategoryID,
		arg.Type,
		arg.StockTracked,
		arg.BaseUom,
		arg.PurchaseUom,
		arg.SalesUom,
		arg.PurchaseToBaseFactor,
		arg.SalesToBaseFactor,
		arg.PurchasePrice,
		arg.SellingPrice,
		arg.MinSellingPrice,
		arg.MinStockQty,
		arg.Status,
		arg.Summary,
		arg.Attributes,
		arg.Now,
		arg.UpdatedBy,
		arg.ID,
	)
	return err
}
